package io.github.jhipster.sample.service;

import io.github.jhipster.sample.repository.OperationRepository;
import io.github.jhipster.sample.service.dto.OperationDTO;
import io.github.jhipster.sample.service.mapper.OperationMapper;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Service for the business rules around {@link io.github.jhipster.sample.domain.Operation}.
 */
@Service
@Transactional
public class OperationService {

    private static final Logger LOG = LoggerFactory.getLogger(OperationService.class);

    static final Duration RECENT_PERIOD = Duration.ofDays(30);

    private final OperationRepository operationRepository;

    private final OperationMapper operationMapper;

    private final Clock clock;

    public OperationService(OperationRepository operationRepository, OperationMapper operationMapper, Clock clock) {
        this.operationRepository = operationRepository;
        this.operationMapper = operationMapper;
        this.clock = clock;
    }

    /**
     * Get the operations dated within the last 30 days.
     *
     * @param pageable the pagination information.
     * @return the page of recent operations.
     */
    @Transactional(readOnly = true)
    public Page<OperationDTO> findRecent(Pageable pageable) {
        LOG.debug("Request to get recent Operations");
        Instant now = Instant.now(clock);
        return operationRepository.findAllByDateBetween(now.minus(RECENT_PERIOD), now, pageable).map(operationMapper::toDto);
    }
}
EOF
